CREATE TRIGGER `pdf_repairs_insert` BEFORE INSERT ON `pdf_repairs` WHEN NEW.original_key IS NOT (CASE NEW.subject_kind WHEN 'offer' THEN (SELECT d.pdf_r2_key FROM documents d WHERE d.id = NEW.subject_id AND d.type IN ('proposal', 'estimate') AND d.frozen_at IS NOT NULL AND d.pdf_sha256 IS NOT NULL AND d.redacted_at IS NULL AND NOT EXISTS (SELECT 1 FROM clients z WHERE z.id = d.client_id AND z.anonymised_at IS NOT NULL) AND coalesce((d.status IN ('sent', 'viewed') AND d.valid_until >= date((NEW.requested_at) / 1000, 'unixepoch', '+330 minutes') AND NOT EXISTS (SELECT 1 FROM documents n WHERE n.version_group_id = d.version_group_id AND n.version > d.version AND n.frozen_at IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM documents g WHERE g.version_group_id = d.version_group_id AND g.status IN ('accepted', 'converted'))), 0) = 0) WHEN 'certificate' THEN (SELECT ce.r2_key FROM acceptance_certificates ce JOIN acceptances a ON a.id = ce.acceptance_id JOIN documents d ON d.id = a.document_id WHERE ce.acceptance_id = NEW.subject_id AND d.redacted_at IS NULL AND NOT EXISTS (SELECT 1 FROM clients z WHERE z.id = d.client_id AND z.anonymised_at IS NOT NULL)) WHEN 'deed' THEN (SELECT e.unsigned_r2_key FROM deeds e WHERE e.id = NEW.subject_id AND e.status IN ('final', 'signed') AND e.unsigned_sha256 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM clients z WHERE z.id = e.client_id AND z.anonymised_at IS NOT NULL)) WHEN 'invoice' THEN (SELECT d.pdf_r2_key FROM documents d WHERE d.id = NEW.subject_id AND d.type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note') AND d.frozen_at IS NOT NULL AND d.pdf_sha256 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM clients z WHERE z.id = d.client_id AND z.anonymised_at IS NOT NULL)) WHEN 'supplier' THEN (SELECT substr(d.pdf_r2_key, 1, length(d.pdf_r2_key) - 4) || '-supplier.pdf' FROM documents d WHERE d.id = NEW.subject_id AND d.type IN ('tax_invoice', 'export_invoice', 'credit_note', 'debit_note') AND d.frozen_at IS NOT NULL AND d.pdf_sha256 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM clients z WHERE z.id = d.client_id AND z.anonymised_at IS NOT NULL)) WHEN 'receipt' THEN (SELECT d.pdf_r2_key FROM documents d WHERE d.id = NEW.subject_id AND d.type = 'receipt' AND d.frozen_at IS NOT NULL AND d.status IN ('issued', 'void') AND d.pdf_sha256 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM clients z WHERE z.id = d.client_id AND z.anonymised_at IS NOT NULL)) END) BEGIN SELECT RAISE(ABORT, 'pdf_repairs_insert: a rebuild names a subject that may be rebuilt now and its own recorded key'); END;
--> statement-breakpoint
CREATE TRIGGER `pdf_repairs_insert_n` BEFORE INSERT ON `pdf_repairs` WHEN NEW.n IS NOT (1 + coalesce((SELECT max(q.n) FROM pdf_repairs q WHERE q.subject_kind = NEW.subject_kind AND q.subject_id = NEW.subject_id), 0)) BEGIN SELECT RAISE(ABORT, 'pdf_repairs_insert_n: a rebuild takes the next number of its subject'); END;
--> statement-breakpoint
CREATE TRIGGER `pdf_repairs_insert_keys` BEFORE INSERT ON `pdf_repairs` WHEN NEW.new_key IS NOT (substr(NEW.original_key, 1, length(NEW.original_key) - 4) || '-r' || CAST(NEW.n AS INTEGER) || '.pdf') OR NEW.old_key IS NOT (coalesce((SELECT r.new_key FROM pdf_repair_results r WHERE r.original_key = NEW.original_key AND r.outcome = 'rebuilt' ORDER BY r.n DESC LIMIT 1), NEW.original_key)) BEGIN SELECT RAISE(ABORT, 'pdf_repairs_insert_keys: a rebuild writes to the original key with -r and its number, and names the key served as the old one'); END;
--> statement-breakpoint
CREATE TRIGGER `pdf_repair_results_insert` BEFORE INSERT ON `pdf_repair_results` WHEN (SELECT 1 FROM pdf_repairs p WHERE p.id = NEW.repair_id) IS NULL
       OR NEW.original_key IS NOT (SELECT p.original_key FROM pdf_repairs p WHERE p.id = NEW.repair_id) OR NEW.n IS NOT (SELECT p.n FROM pdf_repairs p WHERE p.id = NEW.repair_id)
       OR (NEW.outcome = 'rebuilt' AND NEW.new_key IS NOT (SELECT p.new_key FROM pdf_repairs p WHERE p.id = NEW.repair_id))
       OR (NEW.outcome <> 'rebuilt' AND (NEW.new_key IS NOT NULL OR NEW.new_sha256 IS NOT NULL OR NEW.bytes IS NOT NULL))
       OR NEW.completed_at < (SELECT p.requested_at FROM pdf_repairs p WHERE p.id = NEW.repair_id)
       BEGIN SELECT RAISE(ABORT, 'pdf_repair_results_insert: a rebuild result belongs to its request, with its keys, never before it'); END;
